import { test } from 'node:test';
import assert from 'node:assert/strict';
import { topoSort } from '../topo.js';
test('simple chain', () => assert.deepEqual(topoSort({ build: ['compile'], compile: ['fetch'], fetch: [] }), ['fetch', 'compile', 'build']));
test('alphabetical when ready together', () => assert.deepEqual(topoSort({ z: [], a: [], m: ['z', 'a'] }), ['a', 'z', 'm']));
test('implicit tasks', () => assert.deepEqual(topoSort({ app: ['lib', 'util'] }), ['lib', 'util', 'app']));
test('diamond', () => assert.deepEqual(topoSort({ d: ['b', 'c'], b: ['a'], c: ['a'], a: [] }), ['a', 'b', 'c', 'd']));
test('every task after its deps on a bigger graph', () => {
  const deps = { a: ['b', 'c'], b: ['d'], c: ['d', 'e'], d: ['f'], e: ['f'], f: [], g: ['a', 'e'], h: [] };
  const order = topoSort(deps);
  assert.equal(order.length, 8);
  for (const [t, ds] of Object.entries(deps)) for (const d of ds) assert.ok(order.indexOf(d) < order.indexOf(t), d + ' before ' + t);
});
test('cycle', () => {
  assert.throws(() => topoSort({ a: ['b'], b: ['c'], c: ['a'] }), (e) => /a -> b -> c -> a|b -> c -> a -> b|c -> a -> b -> c/.test(e.message));
  assert.throws(() => topoSort({ x: ['x'] }), /x -> x/);
});
test('empty', () => assert.deepEqual(topoSort({}), []));

