export function topoSort(deps) {
  const graph = new Map();
  for (const [t, ds] of Object.entries(deps)) {
    graph.set(t, ds);
    for (const d of ds) if (!graph.has(d) && !(d in deps)) graph.set(d, []);
  }
  const names = [...graph.keys()].sort();
  const indeg = new Map(names.map((n) => [n, graph.get(n).length]));
  const users = new Map(names.map((n) => [n, []]));
  for (const n of names) for (const d of graph.get(n)) users.get(d).push(n);
  const out = [];
  let ready = names.filter((n) => indeg.get(n) === 0);
  while (ready.length) {
    ready.sort();
    const n = ready.shift();
    out.push(n);
    for (const u of users.get(n)) {
      indeg.set(u, indeg.get(u) - 1);
      if (indeg.get(u) === 0) ready.push(u);
    }
  }
  if (out.length === names.length) return out;
  // Find a cycle among what is left
  const left = new Set(names.filter((n) => !out.includes(n)));
  const start = [...left].sort()[0];
  const path = [start];
  const seen = new Set([start]);
  let cur = start;
  for (;;) {
    const next = graph.get(cur).filter((d) => left.has(d)).sort()[0];
    if (seen.has(next)) {
      path.push(next);
      throw new Error('cycle: ' + path.slice(path.indexOf(next)).join(' -> '));
    }
    seen.add(next);
    path.push(next);
    cur = next;
  }
}
